LINGUE = (('IT', IT), ('SQ', SQ), ('EN', EN), ('ES', ES))

def _forma(x):
    """Struttura di un testo: chiavi dei dizionari, lunghezza di liste e tuple, tipo delle foglie."""
    if isinstance(x, dict): return {k: _forma(v) for k, v in sorted(x.items())}
    if isinstance(x, (list, tuple)): return [_forma(v) for v in x]
    return 's'

def controlla():
    """Le quattro lingue devono avere la stessa struttura: se manca una riga o una cella, si ferma qui."""
    base = _forma(IT); errori = []
    for nome, L in LINGUE[1:]:
        if _forma(L) != base:
            def conf(a, b, percorso=''):
                if isinstance(a, dict) and isinstance(b, dict):
                    for k in sorted(set(a) | set(b)):
                        if k not in a or k not in b: errori.append(f'{nome}: chiave {percorso}/{k} non coincide')
                        else: conf(a[k], b[k], f'{percorso}/{k}')
                elif isinstance(a, list) and isinstance(b, list):
                    if len(a) != len(b): errori.append(f'{nome}: {percorso} ha {len(b)} voci invece di {len(a)}')
                    else:
                        for i, (x, y) in enumerate(zip(a, b)): conf(x, y, f'{percorso}[{i}]')
                elif a != b: errori.append(f'{nome}: {percorso} di tipo diverso')
            conf(base, _forma(L))
    assert not errori, '\n'.join(errori)
    return True
